@@ -0,0 +1,18 @@
+type Handler = (payload: unknown) => void;
+
+function handleUserCreated(payload: unknown): void {
+  console.log("provisioning workspace for", payload);
+}
+
+function handleUserDeleted(payload: unknown): void {
+  console.log("scheduling data purge for", payload);
+}
+
+const handlers: Record<string, Handler> = {
+  "user.created": handleUserCreated,
+  "user.deleted": handleUserDeleted,
+};
+
+export function dispatch(event: string, payload: unknown): void {
+  handlers[event]?.(payload);
+}
